 field.append(select);const status=document.createElement('p');status.id='asrStatus';status.setAttribute('role','status');const check=document.createElement('button');check.textContent='Preparar reconhecimento';check.id='checkASR';box.append(field,status,check);const cancel=document.createElement('button');cancel.id='cancelRecognitionPreparation';cancel.textContent='Cancelar preparação';cancel.hidden=true;cancel.onclick=()=>select.value==='paraformer'?window.paraformerASR.abort():window.deviceASR?.abort('Preparação cancelada. Você pode escolher Reconhecimento do navegador.');box.append(cancel);
 const punctuationLabel=document.createElement('label');punctuationLabel.className='original-toggle';const punctuationToggle=document.createElement('input');punctuationToggle.type='checkbox';punctuationToggle.id='autoPunctuation';punctuationToggle.checked=true;punctuationLabel.append(punctuationToggle,document.createTextNode('Pontuação automática'));const punctuationStatus=document.createElement('small');punctuationStatus.id='punctuationStatus';punctuationStatus.textContent='Preserva as palavras. Vírgulas e perguntas são estimadas pelo contexto.';box.append(punctuationLabel,punctuationStatus);
 let serverMode=false,captureActive=false,allowPreparation=false,preparing=false;
